        const t = bg.next('text', 'o-ch-annot-label');
        chSetText(t, a.label);
        chAttr(t, vertical ? { x: clamp(p0, lay.x0, lay.x1) + 6, y: lay.y0 + fs + 2, 'text-anchor': 'start' } : { x: lay.x1 - 6, y: clamp(p0, lay.y0, lay.y1) + fs + 2, 'text-anchor': 'end' });
