    on(this._thead, 'change', '[data-fkey]', (e, el) => { setRow.cancel(); this._filterRowSet(el.dataset.fkey, el); });
    on(this._thead, 'focusin pointerdown', 'select[data-fsel]', (e, el) => this._fillSelect(el));
