    const wrap = h('div', { class: 'o-dt-modal' }, back, box);
    const x = h('button', { type: 'button', class: 'o-btn-close', 'aria-label': this.t('table.close') });
    box.append(h('div', { class: 'o-dt-dialog-head' }, h('h2', { class: 'o-dt-dialog-title', id }, title), x));
    portal(wrap, this);
